var a=`1061-nasi-kerabu`;var s=`world-1061`;var t=`MY`;var n=`southeast-asia`;var o=4;var r=59;var l={en:`Nasi Kerabu`,ua:`Насі керабу`};var d={en:`Nasi Kerabu is a dish from Malaysia prepared with jasmine rice, lemongrass, pandan leaves, tilapia. This is a home-scale version with measured ingredients in the individual steps where they are used. Nasi kerabu is traditionally blue from butterfly-pea flowers; those flowers are absent, so the rice here is not blue.`,ua:`Насі керабу, страва кухні країни Малайзія, яку готують із таких продуктів: рис жасмин, лемонграс, листя пандану, тилапія. Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Традиційний насі керабу синій від квітів кліторії, яких немає в каталозі; рис у цій версії не синій.`};var u=[{en:`Rinse the rice, add the listed water, stock, coconut milk and aromatics as specified, cover and cook gently for about 26 minutes until tender and the liquid absorbs.`,ua:`Промийте рис, додайте зазначені воду, бульйон, кокосове молоко та прянощі, накрийте й готуйте приблизно 26 хвилин до м’якості та поглинання рідини.`,t:[`rice-washing`,`absorption-cooking`],m:26,i:[[`jasmine-rice`,420,`g`],[`water`,650,`ml`],[`lemongrass`,2,`pcs`],[`pandan-leaves`,2,`leaf`]]},{en:`Heat the pan over medium heat, shape or spoon out portions, and fry for about 13 minutes total until golden on both sides and fully cooked.`,ua:`Розігрійте сковороду на середньому вогні, сформуйте або викладіть порції ложкою й смажте загалом приблизно 13 хвилин до золотистості з обох боків і повної готовності.`,t:[`pan-frying`],m:13,i:[[`tilapia`,560,`g`],[`canola-oil`,45,`ml`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:6,i:[[`desiccated-coconut`,85,`g`],[`lemongrass`,18,`g`],[`cilantro`,20,`g`],[`serrano-pepper`,1,`pcs`]]},{en:`Boil the eggs for about 9 minutes, cool promptly in cold water, peel and prepare as required.`,ua:`Варіть яйця приблизно 9 хвилин, швидко охолодіть у холодній воді, очистьте та підготуйте за потреби.`,t:[`hard-boiling-eggs`],m:9,i:[[`chicken-egg`,3,`pcs`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:5,i:[[`cucumber`,200,`g`],[`mung-bean-sprouts`,160,`g`]]}];var c={slug:a,id:s,country:`MY`,region:n,servings:4,minutes:59,title:l,text:d,steps:u};export{t as country,c as default,s as id,r as minutes,n as region,o as servings,a as slug,u as steps,d as text,l as title};